package dev.veltraph.client.builder;
import dev.veltraph.client.config.*;
import dev.veltraph.client.core.*;
import dev.veltraph.client.input.ScriptingInputLock;
import dev.veltraph.client.service.ClockService;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Actual producer admission/policy with registered module lifecycle and the observed Root tick-before-lock order. */
class Source95AcquisitionAdmissionTest {
 private static final String CONTRACT="{\"WHEAT\":{\"productName\":\"Seeds\",\"resourceComponents\":\"@vanilla\",\"menuTitles\":[\"Seeds\"],\"controls\":{\"instant\":\"Instant\",\"stack\":\"Stack\"},\"maxTotalCoins\":500,\"clickDelayMillis\":100,\"timeoutMillis\":7000}}";
 private static final class Clock implements ClockService {long tick=10,now=100;public long currentTick(){return tick;}public long nowMillis(){return now;}}
 private final class Producer implements AutoCloseable {
  final Clock clock=new Clock();final ModuleManager manager=new ModuleManager();final MapConfigService config=new MapConfigService();
  final Source95AcquisitionBinding binding=Source95AcquisitionBinding.decode(CONTRACT,BuilderCropType.WHEAT);final Source95AcquisitionPolicy policy=new Source95AcquisitionPolicy(binding);final Source95AcquisitionAuthority authority=new Source95AcquisitionAuthority();final Source95AcquisitionAdmission admission=new Source95AcquisitionAdmission();
  Object p=new Object(),w=new Object(),c=new Object(),clockIdentity=clock;boolean alive=true,thread=true,gameMode=true,closed=true,cursorEmpty=true,grounded=true;int nativeCommandAdmissions;boolean commandOpened;Source95AcquisitionAdmission.Decision decision;
  final AbstractModule module=new AbstractModule(BuilderModule.ID,"Builder admission test",ModuleCategory.BUILDERS){@Override public void onTick(){step();}};
  Producer(){ScriptingInputLock.releaseAll();config.set(BuilderConfig.BUILDER_BUY_RESOURCES,true);config.set(GeneratedBuilderConfig.IRONMAN_MODE,false);config.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.WHEAT);config.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);manager.register(module);module.setEnabled(true);}
  Source95AcquisitionAdmission.Snapshot snapshot(){return new Source95AcquisitionAdmission.Snapshot(clockIdentity,clock.tick,module,BuilderModule.ID,manager.get(BuilderModule.ID).orElse(null),manager.inputOwner().orElse(null),p,w,c,module.isEnabled(),thread,alive,gameMode,closed,cursorEmpty,grounded,ScriptingInputLock.isActive(),ScriptingInputLock.ownerModuleId());}
  void step(){if(admission.admitted())return;decision=admission.poll(snapshot(),clock.now,binding.timeoutMillis(),policy.validate(config,authority));if(decision==Source95AcquisitionAdmission.Decision.ADMITTED&&!commandOpened){assertTrue(snapshot().fullyOwned());assertTrue(policy.validate(config,authority));nativeCommandAdmissions++;commandOpened=true;}}
  // Same waiting-message route as McSource95Acquisition.message; it cannot admit a command.
  void message(){if(admission.waiting())admission.observePendingMessage(config,policy,authority,this::snapshot,clock.now,binding.timeoutMillis());}
  void moduleFrame(){manager.tick();}
  void rootPostModuleLock(){ScriptingInputLock.set(manager.inputOwner().isPresent(),manager.inputOwner().map(dev.veltraph.client.core.Module::id).orElse(null));}
  void nextRootFrame(){clock.tick++;clock.now+=50;}
  @Override public void close(){admission.cancel();manager.stopAll();ScriptingInputLock.releaseAll();}
 }
 @Test void initialAbsentLockDefersWithoutActionThenNextRootBoundFrameAdmitsExactlyOneCommand(){try(var h=new Producer()){h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.WAIT,h.decision);assertTrue(h.admission.waiting());assertEquals(100,h.admission.startMillis());assertTrue(h.policy.revisionEvidenceAvailable());assertEquals(0,h.nativeCommandAdmissions);assertFalse(ScriptingInputLock.isActive());assertEquals(Source95AcquisitionAuthority.State.READY,h.authority.state());h.rootPostModuleLock();h.nextRootFrame();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.ADMITTED,h.decision);assertEquals(1,h.nativeCommandAdmissions);assertTrue(h.admission.admitted());h.nextRootFrame();h.moduleFrame();assertEquals(1,h.nativeCommandAdmissions);}}
 @Test void alreadyFullyOwnedFirstFramePreservesImmediateAdmission(){try(var h=new Producer()){h.rootPostModuleLock();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.ADMITTED,h.decision);assertEquals(100,h.admission.startMillis());assertEquals(1,h.nativeCommandAdmissions);}}
 @Test void secondAbsentFrameCannotRenewDeferralOrLaterAdoptLock(){try(var h=new Producer()){h.moduleFrame();h.nextRootFrame();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);h.rootPostModuleLock();h.nextRootFrame();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);assertEquals(100,h.admission.startMillis());}}
 @Test void foreignInitialOrSecondFrameLockBlocksWithoutNativeCommand(){for(boolean second:List.of(false,true))try(var h=new Producer()){if(second){h.moduleFrame();h.nextRootFrame();}ScriptingInputLock.acquire("foreign-owner");h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);}}
 @Test void policyChangeAndBetweenReadABACannotBeAdoptedAtSecondBoundFrame(){for(int key=0;key<5;key++)for(boolean aba:List.of(false,true))try(var h=new Producer()){h.moduleFrame();switch(key){case 0->h.config.set(BuilderConfig.BUILDER_BUY_RESOURCES,false);case 1->h.config.set(GeneratedBuilderConfig.IRONMAN_MODE,true);case 2->h.config.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.CARROT);case 3->h.config.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("500","100"));case 4->h.config.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT.replace("Stack","Other"));default->throw new AssertionError();}if(aba){h.config.set(BuilderConfig.BUILDER_BUY_RESOURCES,true);h.config.set(GeneratedBuilderConfig.IRONMAN_MODE,false);h.config.set(BuilderConfig.BUILDER_CROP_TYPE,BuilderCropType.WHEAT);h.config.set(GeneratedBuilderConfig.SOURCE95_CROP_ACQUISITION_BINDING,CONTRACT);}h.rootPostModuleLock();h.nextRootFrame();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,h.authority.state());assertEquals(0,h.nativeCommandAdmissions);assertEquals(100,h.admission.startMillis());}}
 @Test void actualPWCAndNativeStartupReadinessChangesBetweenFramesBlockBeforeAction(){for(int field=0;field<10;field++)try(var h=new Producer()){h.moduleFrame();switch(field){case 0->h.p=new Object();case 1->h.w=new Object();case 2->h.c=new Object();case 3->h.alive=false;case 4->h.thread=false;case 5->h.gameMode=false;case 6->h.closed=false;case 7->h.cursorEmpty=false;case 8->h.grounded=false;case 9->h.module.setEnabled(false);default->throw new AssertionError();}h.rootPostModuleLock();h.nextRootFrame();h.step();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);}}
 @Test void exactNextRootTickClockIdentityAndOriginalDeadlineAreRequired(){for(int variant=0;variant<5;variant++)try(var h=new Producer()){h.moduleFrame();h.rootPostModuleLock();h.nextRootFrame();switch(variant){case 0->h.clock.tick=10;case 1->h.clock.tick=9;case 2->h.clock.tick=12;case 3->h.clockIdentity=new Clock();case 4->h.clock.now=7100;default->throw new AssertionError();}h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);assertEquals(100,h.admission.startMillis());}}
 @Test void cancellationOrRawMessageObservationCannotRearmOrAdvancePendingAdmission(){try(var h=new Producer()){h.moduleFrame();assertTrue(h.admission.observePending(h.snapshot(),h.clock.now,7000,h.policy.validate(h.config,h.authority)));assertEquals(0,h.nativeCommandAdmissions);assertFalse(h.admission.admitted());h.admission.cancel();h.rootPostModuleLock();h.nextRootFrame();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);}try(var h=new Producer()){h.moduleFrame();Object original=h.w;h.w=new Object();assertFalse(h.admission.observePending(h.snapshot(),h.clock.now,7000,h.policy.validate(h.config,h.authority)));h.w=original;h.rootPostModuleLock();h.nextRootFrame();h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);}}
 @Test void pendingMessage150ThenNextOwnedFrame140PermanentlyBlocksEvenAfter160(){try(var h=new Producer()){h.moduleFrame();assertEquals(100,h.admission.startMillis());h.clock.now=150;h.message();assertEquals(150,h.admission.lastObservedMillis());assertEquals(0,h.nativeCommandAdmissions);h.rootPostModuleLock();h.nextRootFrame();h.clock.now=140;h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);assertEquals(100,h.admission.startMillis());h.clock.now=160;h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);}}
 @Test void repeatedPendingMessages150Then140PoisonAuthorityBeforeAnyOwnedTick(){try(var h=new Producer()){h.moduleFrame();h.clock.now=150;h.message();h.clock.now=140;h.message();assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,h.authority.state());assertFalse(h.admission.waiting());assertFalse(h.admission.admitted());assertEquals(0,h.nativeCommandAdmissions);h.rootPostModuleLock();h.nextRootFrame();h.clock.now=160;h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);assertEquals(100,h.admission.startMillis());}}
 @Test void timeBelowInitialOrEqualSampleAndOriginalDeadlineHaveExplicitStartupSemantics(){try(var h=new Producer()){h.moduleFrame();h.clock.now=99;h.message();assertEquals(Source95AcquisitionAuthority.State.UNKNOWN,h.authority.state());h.rootPostModuleLock();h.nextRootFrame();h.clock.now=100;h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.BLOCKED,h.decision);assertEquals(0,h.nativeCommandAdmissions);}try(var h=new Producer()){h.moduleFrame();h.clock.now=150;h.message();h.message();h.rootPostModuleLock();h.nextRootFrame();h.clock.now=150;h.moduleFrame();assertEquals(Source95AcquisitionAdmission.Decision.ADMITTED,h.decision);assertEquals(1,h.nativeCommandAdmissions);assertEquals(100,h.admission.startMillis());}}
 @Test void admittedStartupHelperIsNotPolledAsAnActiveMenuGuard(){try(var h=new Producer()){h.rootPostModuleLock();h.moduleFrame();assertTrue(h.admission.admitted());h.closed=false;h.clock.now=50;h.moduleFrame();assertEquals(1,h.nativeCommandAdmissions);assertThrows(IllegalStateException.class,()->h.admission.poll(h.snapshot(),h.clock.now,7000,true));/* Actual port uses its existing active policy/PWC/menu/ISSUED/time/receipt guards after admission. No continuous monotonic-clock guarantee is claimed by this startup-only helper. */}}

}
